CREATE TABLE "sponsorship_media_kits" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade, "owner_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict, "name" text NOT NULL, "headline" text NOT NULL, "bio" text NOT NULL DEFAULT '', "audience_proof" json NOT NULL DEFAULT '{}'::json, "case_studies" json NOT NULL DEFAULT '[]'::json, "asset_ids" json NOT NULL DEFAULT '[]'::json, "status" text NOT NULL DEFAULT 'draft', "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "sponsorship_media_kits_business_name_unique" UNIQUE ("business_id","name"));
CREATE TABLE "sponsorship_rate_cards" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade, "name" text NOT NULL, "currency" text NOT NULL DEFAULT 'usd', "items" json NOT NULL DEFAULT '[]'::json, "status" text NOT NULL DEFAULT 'active', "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "sponsorship_rate_cards_business_name_unique" UNIQUE ("business_id","name"));
CREATE TABLE "sponsor_deals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade, "owner_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict, "brand_name" text NOT NULL, "contact_id" integer REFERENCES "contacts"("id") ON DELETE set null, "campaign_id" uuid REFERENCES "campaigns"("id") ON DELETE set null, "title" text NOT NULL, "description" text NOT NULL DEFAULT '', "stage" text NOT NULL DEFAULT 'lead', "currency" text NOT NULL DEFAULT 'usd', "proposed_value_cents" integer NOT NULL DEFAULT 0, "contracted_value_cents" integer NOT NULL DEFAULT 0, "disclosure" text NOT NULL DEFAULT '#ad', "usage_rights" json NOT NULL, "renewal_at" timestamp, "won_at" timestamp, "lost_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "sponsor_deals_stage_check" CHECK ("stage" IN ('lead','qualified','proposal','negotiation','contracted','production','invoiced','paid','renewal','lost')));
CREATE INDEX "sponsor_deals_business_stage_idx" ON "sponsor_deals" ("business_id","stage","updated_at");
CREATE TABLE "sponsorship_proposals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "deal_id" uuid NOT NULL REFERENCES "sponsor_deals"("id") ON DELETE cascade, "created_by_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict, "version" integer NOT NULL, "summary" text NOT NULL, "value_cents" integer NOT NULL, "valid_until" timestamp NOT NULL, "deliverables" json NOT NULL, "payment_terms" text NOT NULL, "cancellation_terms" text NOT NULL DEFAULT '', "usage_rights" json NOT NULL, "status" text NOT NULL DEFAULT 'draft', "accepted_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "sponsorship_proposals_deal_version_unique" UNIQUE ("deal_id","version"), CONSTRAINT "sponsorship_proposals_status_check" CHECK ("status" IN ('draft','sent','viewed','changes_requested','accepted','declined','expired')));
CREATE TABLE "sponsorship_contracts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "deal_id" uuid NOT NULL UNIQUE REFERENCES "sponsor_deals"("id") ON DELETE cascade, "proposal_id" uuid NOT NULL REFERENCES "sponsorship_proposals"("id") ON DELETE restrict, "document_id" integer REFERENCES "documents"("id") ON DELETE set null, "status" text NOT NULL DEFAULT 'draft', "creator_signed_name" text, "brand_signed_name" text, "creator_signed_at" timestamp, "brand_signed_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "sponsorship_contracts_status_check" CHECK ("status" IN ('draft','sent','partially_signed','executed','void')));
CREATE TABLE "sponsorship_milestones" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "deal_id" uuid NOT NULL REFERENCES "sponsor_deals"("id") ON DELETE cascade, "name" text NOT NULL, "description" text NOT NULL DEFAULT '', "due_at" timestamp, "amount_cents" integer NOT NULL DEFAULT 0, "status" text NOT NULL DEFAULT 'pending', "approved_by_user_id" integer REFERENCES "users"("id") ON DELETE set null, "approved_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "sponsorship_milestones_status_check" CHECK ("status" IN ('pending','in_progress','submitted','approved','invoiced','paid','cancelled')));
CREATE TABLE "sponsorship_invoices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "deal_id" uuid NOT NULL REFERENCES "sponsor_deals"("id") ON DELETE restrict, "milestone_id" uuid REFERENCES "sponsorship_milestones"("id") ON DELETE set null, "invoice_number" text NOT NULL UNIQUE, "amount_cents" integer NOT NULL, "currency" text NOT NULL, "due_at" timestamp NOT NULL, "status" text NOT NULL DEFAULT 'draft', "provider_invoice_reference" text, "paid_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now(), "updated_at" timestamp NOT NULL DEFAULT now(), CONSTRAINT "sponsorship_invoices_status_check" CHECK ("status" IN ('draft','issued','viewed','partially_paid','paid','past_due','void','refunded')));
CREATE TABLE "sponsorship_performance_snapshots" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "deal_id" uuid NOT NULL REFERENCES "sponsor_deals"("id") ON DELETE cascade, "distribution_job_id" uuid REFERENCES "distribution_jobs"("id") ON DELETE set null, "source" text NOT NULL DEFAULT 'manual', "metrics" json NOT NULL DEFAULT '{}'::json, "captured_by_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict, "captured_at" timestamp NOT NULL DEFAULT now());
CREATE INDEX "sponsorship_performance_deal_captured_idx" ON "sponsorship_performance_snapshots" ("deal_id","captured_at");
CREATE TABLE "sponsorship_portal_tokens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "deal_id" uuid NOT NULL REFERENCES "sponsor_deals"("id") ON DELETE cascade, "token_hash" text NOT NULL UNIQUE, "stakeholder_name" text NOT NULL, "stakeholder_email" text NOT NULL, "expires_at" timestamp NOT NULL, "revoked_at" timestamp, "created_at" timestamp NOT NULL DEFAULT now());
